import * as THREE from 'three';

const FLAG=Symbol.for('wenzhou.map-mother.1940s-coast-refinement-v5-installed');
const TERRAIN_URL='../r3-1/data/terrain.json';
const MASK_MAX=2048,EDGE_EPS_DEG=.004,CORE_M=8,FOOT_M=3,FOOT_DILATE_PX=1,XUANMEN_WIDTH_M=1200;
const XUANMEN=[[121.216,28.226],[121.265,28.223],[121.284,28.192]];
const DONGTOU_OPEN=[[120.86,27.82],[120.94,27.76],[121.08,27.75],[121.20,27.79],[121.27,27.88],[121.25,27.97],[121.13,28.01],[120.99,28.01],[120.89,27.95]];
const CONTROLS=[
 {sheet:'NH51-13',bounds:[120,28,121.5,29],urls:['../../../records/R3_10/HISTORICAL_1953_WATER_CONTROL_NH51_13_P1.geojson','../../../records/R3_10/HISTORICAL_1953_WATER_CONTROL_NH51_13_P2.geojson','../../../records/R3_10/HISTORICAL_1953_WATER_CONTROL_NH51_13_P3.geojson']},
 {sheet:'NG51-1',bounds:[120,27,121.5,28],urls:['../../../records/R3_10/HISTORICAL_1953_WATER_CONTROL_NG51_1.geojson']},
 {sheet:'NH51-14',bounds:[121.5,28,123,29],urls:['../../../records/R3_10/HISTORICAL_1953_WATER_CONTROL_NH51_14.geojson']},
];
function json(u){return fetch(u).then(r=>{if(!r.ok)throw Error(`1940s V5 资料读取失败 (${r.status})`);return r.json();});}
function patchId(){return document.getElementById('location')?.value||document.getElementById('terrain')?.dataset.patch||'';}
function utm(lonDeg,latDeg){const a=6378137,f=1/298.257223563,e2=f*(2-f),ep2=e2/(1-e2),k0=.9996,lon0=123*Math.PI/180,lat=latDeg*Math.PI/180,lon=lonDeg*Math.PI/180,s=Math.sin(lat),c=Math.cos(lat),t=Math.tan(lat),N=a/Math.sqrt(1-e2*s*s),T=t*t,C=ep2*c*c,A=c*(lon-lon0),e4=e2*e2,e6=e4*e2,M=a*((1-e2/4-3*e4/64-5*e6/256)*lat-(3*e2/8+3*e4/32+45*e6/1024)*Math.sin(2*lat)+(15*e4/256+45*e6/1024)*Math.sin(4*lat)-(35*e6/3072)*Math.sin(6*lat));return[500000+k0*N*(A+(1-T+C)*A**3/6+(5-18*T+T*T+72*C-58*ep2)*A**5/120),k0*(M+N*t*(A*A/2+(5-T+9*C+4*C*C)*A**4/24+(61-58*T+T*T+600*C-330*ep2)*A**6/720))];}
function polys(g){const o=[];for(const f of g.features||[]){const q=f.geometry;if(!q)continue;if(q.type==='Polygon')o.push({c:q.coordinates||[],p:f.properties||{}});else if(q.type==='MultiPolygon')for(const x of q.coordinates||[])o.push({c:x,p:f.properties||{}});}return o;}
function bounds(contract,patch){const t=contract.source.transform,e=c=>t[2]+t[0]*(c+.5),n=r=>t[5]+t[4]*(r+.5),e0=e(patch.columnIndices[0]),e1=e(patch.columnIndices.at(-1)),n0=n(patch.rowIndices[0]),n1=n(patch.rowIndices.at(-1));return[Math.min(e0,e1),Math.min(n0,n1),Math.max(e0,e1),Math.max(n0,n1)];}
function pb(r){let w=Infinity,s=Infinity,e=-Infinity,n=-Infinity;for(const a of r)for(const p of a){w=Math.min(w,p[0]);s=Math.min(s,p[1]);e=Math.max(e,p[0]);n=Math.max(n,p[1]);}return[w,s,e,n];}
const intersects=(a,b)=>!(a[2]<b[0]||a[0]>b[2]||a[3]<b[1]||a[1]>b[3]);
function size(b){const dx=b[2]-b[0],dy=b[3]-b[1];return dx>=dy?[MASK_MAX,Math.max(512,Math.round(MASK_MAX*dy/dx))]:[Math.max(512,Math.round(MASK_MAX*dx/dy)),MASK_MAX];}
function canvas(w,h,fill='#000'){const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d',{willReadFrequently:true});x.fillStyle=fill;x.fillRect(0,0,w,h);return[c,x];}
function draw(ctx,rings,b,w,h,fill){ctx.fillStyle=fill;ctx.beginPath();for(const ring of rings){let first=true;for(const[e,n]of ring){const x=(e-b[0])/(b[2]-b[0])*w,y=(b[3]-n)/(b[3]-b[1])*h;if(first){ctx.moveTo(x,y);first=false;}else ctx.lineTo(x,y);}ctx.closePath();}ctx.fill('evenodd');}
function edges(poly,b){const[w,s,e,n]=b,z=new Set();for(const r of poly)for(const[lon,lat]of r){if(Math.abs(lon-w)<=EDGE_EPS_DEG)z.add('w');if(Math.abs(lon-e)<=EDGE_EPS_DEG)z.add('e');if(Math.abs(lat-s)<=EDGE_EPS_DEG)z.add('s');if(Math.abs(lat-n)<=EDGE_EPS_DEG)z.add('n');}return[...z];}
function project(controls,b){const out=[];for(const c of controls)for(const g of c.geos)for(const p of polys(g)){const r=p.c.map(a=>a.map(([lo,la])=>utm(lo,la))),bb=pb(r);if(intersects(bb,b))out.push({sheet:c.sheet,rings:r,touch:edges(p.c,c.bounds),sourcePixelArea:Number(p.p?.pixelArea||0)});}return out;}
function classify(items,base,b,w,h){const full=w*h,ok=[],bad=[],[cc,cx]=canvas(w,h);for(const item of items){cx.clearRect(0,0,w,h);cx.fillStyle='#000';cx.fillRect(0,0,w,h);draw(cx,item.rings,b,w,h,'#fff');const d=cx.getImageData(0,0,w,h).data;let area=0,land=0;for(let i=0;i<d.length;i+=4)if(d[i+1]>=128){area++;if(base[i+1]>=128)land++;}if(!area)continue;const coverage=area/full,lf=land/area,ws=1-lf,ec=item.touch.length;let reason='accepted';if(ec>=2&&item.sourcePixelArea>=8000&&ws<.55)reason='reject-frame-weak-water';else if(coverage>=.20&&lf>=.42)reason='reject-large-land';else if(coverage>=.08&&lf>=.62)reason='reject-large-land';else if(ec>=2&&coverage>=.08&&lf>=.50)reason='reject-frame-background';const q={sheet:item.sheet,reason,coverage:+coverage.toFixed(5),landFraction:+lf.toFixed(5),modernWaterSupport:+ws.toFixed(5)};if(reason==='accepted')ok.push(item);else bad.push(q);}return{ok,bad};}
function markDisk(mask,w,h,cx,cy,r){for(let y=Math.max(0,cy-r);y<=Math.min(h-1,cy+r);y++)for(let x=Math.max(0,cx-r);x<=Math.min(w-1,cx+r);x++)if((x-cx)**2+(y-cy)**2<=r*r)mask[y*w+x]=1;}
function terrainThresholdMasks(terrain,base,candidate,b,w,h){const N=w*h,core=new Uint8Array(N),foot=new Uint8Array(N),pos=terrain.geometry?.attributes?.position;if(!pos)return{core,foot,coreSeeds:0,footSeeds:0};const sx=terrain.scale?.x??1,sz=terrain.scale?.z??1,ce=(b[0]+b[2])*.5,cn=(b[1]+b[3])*.5,mpp=Math.max((b[2]-b[0])/w,(b[3]-b[1])/h);let cs=0,fs=0;for(let i=0;i<pos.count;i++){const elev=pos.getY(i)*1000;if(elev<FOOT_M)continue;const e=ce+pos.getX(i)*sx*1000,n=cn-pos.getZ(i)*sz*1000,x=Math.round((e-b[0])/(b[2]-b[0])*(w-1)),y=Math.round((b[3]-n)/(b[3]-b[1])*(h-1));if(x<0||y<0||x>=w||y>=h)continue;const p=y*w+x,o=p*4;if(base[o+1]<128||candidate[o+1]>=128)continue;markDisk(foot,w,h,x,y,FOOT_DILATE_PX);fs++;if(elev>=CORE_M){markDisk(core,w,h,x,y,1);cs++;}}return{core,foot,coreSeeds:cs,footSeeds:fs,mpp};}
function naturalFootComponents(terrain,base,candidate,b,w,h){const N=w*h,t=terrainThresholdMasks(terrain,base,candidate,b,w,h),seen=new Uint8Array(N),keep=new Uint8Array(N),q=new Int32Array(N);let components=0,keptComponents=0,keptPixels=0;for(let start=0;start<N;start++){if(!t.foot[start]||seen[start])continue;components++;let head=0,tail=0,hasCore=false;seen[start]=1;q[tail++]=start;while(head<tail){const p=q[head++],x=p%w,y=(p/w)|0;hasCore ||= !!t.core[p];const visit=n=>{if(n>=0&&n<N&&t.foot[n]&&!seen[n]){seen[n]=1;q[tail++]=n;}};if(x>0)visit(p-1);if(x+1<w)visit(p+1);if(y>0)visit(p-w);if(y+1<h)visit(p+w);}if(hasCore){keptComponents++;for(let i=0;i<tail;i++){const p=q[i],o=p*4;if(base[o+1]>=128&&candidate[o+1]<128){keep[p]=1;keptPixels++;}}}}return{mask:keep,components,keptComponents,keptPixels,coreSeeds:t.coreSeeds,footSeeds:t.footSeeds,mpp:t.mpp};}
function carveDongtou(ctx,b,w,h){draw(ctx,[DONGTOU_OPEN.map(([lo,la])=>utm(lo,la))],b,w,h,'#000');}
function openXuanmen(ctx,b,w,h){const pts=XUANMEN.map(([lo,la])=>utm(lo,la)).map(([e,n])=>[(e-b[0])/(b[2]-b[0])*w,(b[3]-n)/(b[3]-b[1])*h]),mpp=Math.max((b[2]-b[0])/w,(b[3]-b[1])/h),lw=Math.max(3,XUANMEN_WIDTH_M/mpp);ctx.save();ctx.strokeStyle='#000';ctx.lineWidth=lw;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();pts.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.stroke();ctx.restore();return lw;}
function at(m,b,x,z){const e=(b[0]+b[2])*.5+x*1000,n=(b[1]+b[3])*.5-z*1000,px=Math.floor((e-b[0])/(b[2]-b[0])*m.width),py=Math.floor((b[3]-n)/(b[3]-b[1])*m.height);return px>=0&&py>=0&&px<m.width&&py<m.height&&m.landPixels[(py*m.width+px)*4+1]>=128;}
function filterOsm(o,m,b){const g=o.geometry,pos=g?.attributes?.position,index=g?.index;if(!pos||!index)return{removed:0,kept:0};if(!o.userData.wenzhouMapMotherBaseIndex)o.userData.wenzhouMapMotherBaseIndex=index.array.slice();const base=o.userData.wenzhouMapMotherBaseIndex,kept=[];let removed=0;for(let k=0;k+1<base.length;k+=2){const a=Number(base[k]),bb=Number(base[k+1]),ax=pos.getX(a),az=pos.getZ(a),bx=pos.getX(bb),bz=pos.getZ(bb);if(at(m,b,ax,az)&&at(m,b,bx,bz)&&at(m,b,(ax+bx)/2,(az+bz)/2))kept.push(a,bb);else removed++;}const C=base.constructor;g.setIndex(new THREE.BufferAttribute(new C(kept),1));return{removed,kept:kept.length/2};}
function osm(scene,m,b){let roadHidden=0,buildingHidden=0,objects=0;scene.traverse(o=>{if(!o.userData?.wenzhouOsmEvidence)return;objects++;const r=filterOsm(o,m,b);if(o.userData.kind==='osm-road-centerline-evidence')roadHidden+=r.removed;else if(o.userData.kind==='osm-building-footprint-boundary-evidence')buildingHidden+=r.removed;});document.getElementById('show-osm-roads')?.dispatchEvent(new Event('change'));document.getElementById('show-osm-buildings')?.dispatchEvent(new Event('change'));return{objects,roadHidden,buildingHidden};}
function build(terrain,items,b){const bt=terrain.userData.wenzhouMapMotherBaseAlphaMap||terrain.material?.alphaMap;if(!bt?.image)throw Error('1940s V5 缺少基础 land mask');terrain.userData.wenzhouMapMotherBaseAlphaMap=bt;const[w,h]=size(b),[bc,bx]=canvas(w,h),[lc,lx]=canvas(w,h);bx.drawImage(bt.image,0,0,w,h);const base=bx.getImageData(0,0,w,h).data,q=classify(items,base,b,w,h);if(!q.ok.length)throw Error('1940s V5 没有可用历史水域控制');lx.drawImage(bc,0,0,w,h);for(const i of q.ok)draw(lx,i.rings,b,w,h,'#000');const preDong=lx.getImageData(0,0,w,h).data;carveDongtou(lx,b,w,h);const image=lx.getImageData(0,0,w,h),d=image.data;let dong=0;for(let i=0;i<d.length;i+=4)if(preDong[i+1]>=128&&d[i+1]<128)dong++;const natural=naturalFootComponents(terrain,base,d,b,w,h);let restored=0;for(let p=0;p<natural.mask.length;p++)if(natural.mask[p]){const o=p*4;if(base[o+1]>=128&&d[o+1]<128){d[o]=d[o+1]=d[o+2]=255;d[o+3]=255;restored++;}}lx.putImageData(image,0,0);const preX=lx.getImageData(0,0,w,h).data;openXuanmen(lx,b,w,h);const final=lx.getImageData(0,0,w,h),fd=final.data;let water=0,reclaimed=0,xforced=0;for(let i=0;i<fd.length;i+=4)if(fd[i+1]<128){water++;if(base[i+1]>=128)reclaimed++;if(preX[i+1]>=128)xforced++;}const[sc,sx]=canvas(w,h);sx.filter='blur(0.55px)';sx.drawImage(lc,0,0);sx.filter='none';const texture=new THREE.CanvasTexture(sc);texture.minFilter=THREE.LinearMipmapLinearFilter;texture.magFilter=THREE.LinearFilter;texture.generateMipmaps=true;texture.anisotropy=4;texture.needsUpdate=true;return{texture,landPixels:fd,width:w,height:h,historicalWaterPixels:water,reclaimedPixels:reclaimed,dongtouForcedWaterPixels:dong,xuanmenForcedWaterPixels:xforced,naturalRestoredPixels:restored,naturalComponents:natural.components,naturalKeptComponents:natural.keptComponents,naturalCoreSeeds:natural.coreSeeds,naturalFootSeeds:natural.footSeeds,naturalKeptPixels:natural.keptPixels,accepted:q.ok.length,rejected:q.bad.length,rejectedControls:q.bad};}
function apply(scene,terrain,m){const old=terrain.userData.wenzhouMapMotherV5AlphaMap;if(old&&old!==m.texture)old.dispose?.();terrain.userData.wenzhouMapMotherV5AlphaMap=m.texture;terrain.material.alphaMap=m.texture;terrain.material.alphaTest=.30;terrain.material.alphaToCoverage=true;terrain.material.needsUpdate=true;let sea=false;scene.traverse(o=>{if(o.userData?.wenzhouSeaDemo&&o.material?.uniforms?.uLandMask){o.material.uniforms.uLandMask.value=m.texture;o.material.needsUpdate=true;sea=true;}});return sea;}
export function installHistory1942CoastRefinementV5(){if(window[FLAG])return;window[FLAG]=true;const contractP=json(TERRAIN_URL),controlP=Promise.all(CONTROLS.map(async c=>({...c,geos:await Promise.all(c.urls.map(json))})));let latest=null,token=0,active=null;window.addEventListener('wenzhou:terrain-added',e=>{const d=e.detail||{};if(d.scene?.isScene&&d.terrain?.isMesh&&d.patchId)latest=d;});window.addEventListener('wenzhou:map-mother-1940s-refined-v4',async e=>{const id=e.detail?.patchId;if(!id||!latest||latest.patchId!==id||patchId()!==id)return;const t=++token,c=document.getElementById('terrain');try{const[contract,controls]=await Promise.all([contractP,controlP]);if(t!==token||patchId()!==id)return;const p=contract.patches.find(x=>x.id===id);if(!p)throw Error(`1940s V5 缺少 patch ${id}`);const b=bounds(contract,p),items=project(controls,b),pos=latest.terrain.geometry?.attributes?.position,ver=pos?.version??0,count=pos?.count??0,m=build(latest.terrain,items,b);if(t!==token||patchId()!==id){m.texture.dispose();return;}const sea=apply(latest.scene,latest.terrain,m),geometryPreserved=latest.terrain.geometry?.attributes?.position===pos&&(pos?.version??0)===ver&&(pos?.count??0)===count,state=window.__wenzhouMapMother1940s||{};Object.assign(state,{schema:'wenzhou-map-mother/1940s-land-water-delta-v5',coastRefinement:'candidate-water-local-elevation-foot-components',maskWidth:m.width,maskHeight:m.height,historicalWaterPixels:m.historicalWaterPixels,reclaimedPixels:m.reclaimedPixels,naturalCoreM:CORE_M,naturalFootM:FOOT_M,naturalFootDilatePx:FOOT_DILATE_PX,naturalComponents:m.naturalComponents,naturalKeptComponents:m.naturalKeptComponents,naturalCoreSeeds:m.naturalCoreSeeds,naturalFootSeeds:m.naturalFootSeeds,naturalReliefRestoredPixels:m.naturalRestoredPixels,dongtouReclamationRollback:'derived-open-water-lowland',dongtouForcedWaterPixels:m.dongtouForcedWaterPixels,xuanmenConnectivity:'forced-open-derived-topology',xuanmenCorridorWidthM:XUANMEN_WIDTH_M,xuanmenForcedWaterPixels:m.xuanmenForcedWaterPixels,terrainGeometryPreserved:geometryPreserved,seaMaskUpdated:sea,acceptedControlPolygons:m.accepted,rejectedControlPolygons:m.rejected,rejectedControls:m.rejectedControls,storage:'runtime-derived-vector-plus-local-elevation-components-no-epoch-dem-copy'});window.__wenzhouMapMother1940s=state;const om=osm(latest.scene,m,b);state.osmHistoricalWaterMask=om;active={scene:latest.scene,m,b,id,state};if(c){c.dataset.history1940sRefined='true';c.dataset.history1940sRefinementVersion='v5';c.dataset.history1940sMaskWidth=String(m.width);c.dataset.history1940sMaskHeight=String(m.height);c.dataset.history1940sHistoricalWaterPixels=String(m.historicalWaterPixels);c.dataset.history1940sReclaimedPixels=String(m.reclaimedPixels);c.dataset.history1940sNaturalReliefRestoredPixels=String(m.naturalRestoredPixels);c.dataset.history1940sNaturalComponents=String(m.naturalComponents);c.dataset.history1940sNaturalKeptComponents=String(m.naturalKeptComponents);c.dataset.history1940sDongtouForcedWaterPixels=String(m.dongtouForcedWaterPixels);c.dataset.history1940sXuanmenForcedWaterPixels=String(m.xuanmenForcedWaterPixels);c.dataset.history1940sXuanmenConnectivity='open';c.dataset.history1940sTerrainGeometryPreserved=String(geometryPreserved);c.dataset.history1940sRoadSegmentsHiddenWater=String(om.roadHidden);c.dataset.history1940sBuildingSegmentsHiddenWater=String(om.buildingHidden);c.dataset.history1940sSeaMaskUpdated=String(sea);c.dataset.history1940sRefinementError='';}const card=document.getElementById('history-1942-card');if(card){card.querySelector('strong').textContent='1940s Map Mother · 海岸精修 V5';card.querySelector('span').textContent=`山体岛按本地高程恢复 · 低平围垦退水 ${m.reclaimedPixels.toLocaleString()} px · 玄门湾贯通`;card.querySelector('small').textContent='候选历史水域内，只有 ≥3m 坡面且与 ≥8m 山核连通的自然地形才恢复；低平填海、堤路和人工连接保持为水。原 DEM 顶点高度不改。';}window.dispatchEvent(new CustomEvent('wenzhou:map-mother-1940s-refined-v5',{detail:state}));}catch(err){if(c)c.dataset.history1940sRefinementError=String(err.message||err);console.error(err);}});const c=document.getElementById('terrain');if(c)new MutationObserver(()=>{if(!active)return;if(c.dataset.osmLoaded==='true'&&c.dataset.osmPatch===active.id){const om=osm(active.scene,active.m,active.b);active.state.osmHistoricalWaterMask=om;c.dataset.history1940sRoadSegmentsHiddenWater=String(om.roadHidden);c.dataset.history1940sBuildingSegmentsHiddenWater=String(om.buildingHidden);}}).observe(c,{attributes:true,attributeFilter:['data-osm-loaded','data-osm-patch']});}
